class Ability(models.Model):
    """Carbon 制造业务模块的能力表（public.ability），用于维护能力相关业务数据。"""
    # 第 1 列：记录标识 id（text，非空；默认值：id('abil'::text)）
    id = models.TextField(verbose_name="记录标识", primary_key=True, help_text="存储能力的记录标识；PostgreSQL 类型：text。")
    # 第 2 列：名称 name（text，非空）
    name = models.TextField(verbose_name="名称", help_text="存储能力的名称；PostgreSQL 类型：text。")
    # 第 3 列：能力曲线 curve（jsonb，非空；默认值：'{"data": [{"id": 0,"week": 0,"value": 50},{"id": 1,"week": 1,"value": 80},{"id": 2,"week": 2,"value": 90},{"id": 3,"week": 3,"value": 100}]}'::jsonb）
    curve = models.JSONField(verbose_name="能力曲线", help_text="存储能力的能力曲线；PostgreSQL 类型：jsonb。")
    # 第 4 列：影子周数 shadowWeeks（numeric，非空；默认值：0）
    shadowWeeks = models.DecimalField(max_digits=32, decimal_places=16, verbose_name="影子周数", help_text="存储能力的影子周数；PostgreSQL 类型：numeric。")
    # 第 5 列：启用状态 active（boolean，非空；默认值：true）
    active = models.BooleanField(verbose_name="启用状态", help_text="存储能力的启用状态；PostgreSQL 类型：boolean。")
    # 第 6 列：公司租户标识 companyId（text，非空）
    # 外键：关联 public.company(id)，删除时 CASCADE。
    companyId = models.ForeignKey("Company", models.DO_NOTHING, db_column="companyId", verbose_name="公司租户标识", help_text="关联公司记录，作为能力的公司租户标识；PostgreSQL 类型：text。")
    # 第 7 列：创建时间 createdAt（timestamp with time zone，非空；默认值：now()）
    createdAt = models.DateTimeField(verbose_name="创建时间", auto_now_add=True, help_text="记录该业务记录的创建时间；PostgreSQL 类型：timestamp with time zone。")
    # 第 8 列：创建人 createdBy（text，非空）
    # 外键：关联 public.user(id)，删除时 CASCADE。
    createdBy = models.ForeignKey("User", models.DO_NOTHING, db_column="createdBy", verbose_name="创建人", help_text="关联用户记录，作为能力的创建人；PostgreSQL 类型：text。")
    # 第 9 列：更新时间 updatedAt（timestamp with time zone，可为空）
    updatedAt = models.DateTimeField(verbose_name="更新时间", blank=True, null=True, help_text="记录该业务记录的最后更新时间；PostgreSQL 类型：timestamp with time zone。")
    # 第 10 列：更新人 updatedBy（text，可为空）
    # 外键：关联 public.user(id)，删除时 CASCADE。
    updatedBy = models.ForeignKey("User", models.DO_NOTHING, db_column="updatedBy", verbose_name="更新人", blank=True, null=True, help_text="关联用户记录，作为能力的更新人；PostgreSQL 类型：text。")

    class Meta:
        managed = False
        db_table = "ability"
        verbose_name = "Carbon 制造业务模块的能力表（public.ability），用于维护能力相关业务数据。"
        verbose_name_plural = "Carbon 制造业务模块的能力表（public.ability），用于维护能力相关业务数据。"


